// EMBEDDED BASE64 IMAGES - ZERO DEPENDENCY ON FOLDERS OR RELATIVE PATHS
const BILIARDA_SELECT_IMG = "data:image/jpeg;base64,";
const CHARACTER_HOBO_IMG = "data:image/png;base64,";

// ========================================================
// AUTOMATIC BULLETPROOF IMAGE INJECTION FOR GITHUB PAGES
// (Works even if assets folder was not uploaded)
// ========================================================
function injectBase64Images() {
  document.querySelectorAll('img').forEach(img => {
    const src = img.getAttribute('src') || '';
    if (src.includes('biliarda_select')) {
      img.src = BILIARDA_SELECT_IMG;
    } else if (src.includes('character_hobo')) {
      img.src = CHARACTER_HOBO_IMG;
    }
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', injectBase64Images);
} else {
  injectBase64Images();
}

/* ========================================================
   BILIS QUEST - JAVASCRIPT ENGINE
   Web Audio API Synthesizer & Interactive Choreography
   ======================================================== */

// Global Audio Context for zero-dependency sounds
let audioCtx = null;
let soundEnabled = true;

function initAudio() {
  if (!audioCtx) {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (AudioContext) {
      audioCtx = new AudioContext();
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
}

// Sound Synthesizer Functions
const Sound = {
  playBuzzer() {
    if (!soundEnabled || !audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(110, audioCtx.currentTime);
    osc.frequency.linearRampToValueAtTime(70, audioCtx.currentTime + 0.35);
    gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.35);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.35);
  },

  playAlarm() {
    if (!soundEnabled || !audioCtx) return;
    for (let i = 0; i < 3; i++) {
      setTimeout(() => {
        if (!audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(800, audioCtx.currentTime);
        osc.frequency.setValueAtTime(400, audioCtx.currentTime + 0.08);
        gain.gain.setValueAtTime(0.25, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.16);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.16);
      }, i * 140);
    }
  },

  playWarp() {
    if (!soundEnabled || !audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(220, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1200, audioCtx.currentTime + 0.6);
    gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.6);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.6);
  },

  playJump() {
    if (!soundEnabled || !audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(180, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(650, audioCtx.currentTime + 0.35);
    gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.35);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.35);
  },

  playCrash() {
    if (!soundEnabled || !audioCtx) return;
    // Metal clang & low thud
    const osc1 = audioCtx.createOscillator();
    const osc2 = audioCtx.createOscillator();
    const gain = audioCtx.createGain();

    osc1.type = 'square';
    osc1.frequency.setValueAtTime(320, audioCtx.currentTime);
    osc1.frequency.exponentialRampToValueAtTime(60, audioCtx.currentTime + 0.4);

    osc2.type = 'sawtooth';
    osc2.frequency.setValueAtTime(140, audioCtx.currentTime);
    osc2.frequency.linearRampToValueAtTime(40, audioCtx.currentTime + 0.4);

    gain.gain.setValueAtTime(0.4, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.45);

    osc1.connect(gain);
    osc2.connect(gain);
    gain.connect(audioCtx.destination);

    osc1.start();
    osc2.start();
    osc1.stop(audioCtx.currentTime + 0.45);
    osc2.stop(audioCtx.currentTime + 0.45);
  },

  playBoing() {
    if (!soundEnabled || !audioCtx) return;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(280, audioCtx.currentTime);
    osc.frequency.linearRampToValueAtTime(160, audioCtx.currentTime + 0.15);
    osc.frequency.linearRampToValueAtTime(380, audioCtx.currentTime + 0.35);
    osc.frequency.linearRampToValueAtTime(200, audioCtx.currentTime + 0.5);
    gain.gain.setValueAtTime(0.35, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.5);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.5);
  },

  playPanic() {
    if (!soundEnabled || !audioCtx) return;
    for (let i = 0; i < 4; i++) {
      setTimeout(() => {
        if (!audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(450 + (i % 2) * 200, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.12);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.12);
      }, i * 160);
    }
  },

  playHeavenly() {
    if (!soundEnabled || !audioCtx) return;
    const notes = [523.25, 659.25, 783.99, 1046.50]; // C E G C
    notes.forEach((freq, idx) => {
      setTimeout(() => {
        if (!audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.8);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.8);
      }, idx * 120);
    });
  }
};

/* ========================================================
   DOM ELEMENTS & STATE
   ======================================================== */
const selectScreen = document.getElementById('selectScreen');
const gameScreen = document.getElementById('gameScreen');
const selectBtn = document.getElementById('selectBtn');
const biliardaCard = document.getElementById('biliardaCard');

// Modal Elements
const warningModal = document.getElementById('warningModal');
const modalIcon = document.getElementById('modalIcon');
const modalTitle = document.getElementById('modalTitle');
const modalMessage = document.getElementById('modalMessage');
const modalActionBtn = document.getElementById('modalActionBtn');

// Sound Toggle
const soundToggleBtn = document.getElementById('soundToggleBtn');
const soundIcon = document.getElementById('soundIcon');

// Navigation & Controls
const backToSelectBtn = document.getElementById('backToSelectBtn');
const replayBtn = document.getElementById('replayBtn');
const actionTriggerBtn = document.getElementById('actionTriggerBtn');
const roomTabs = document.querySelectorAll('.room-tab');
const speechBubble = document.getElementById('speechBubble');
const speechText = document.getElementById('speechText');
const sceneDesc = document.getElementById('sceneDescription');
const fxLayer = document.getElementById('fxLayer');

// State Tracking
let selectClickCount = 0;
let currentRoom = 'jikia';
let isAnimating = false;
let speechTimeout = null;

/* ========================================================
   SOUND TOGGLE
   ======================================================== */
soundToggleBtn.addEventListener('click', () => {
  initAudio();
  soundEnabled = !soundEnabled;
  soundIcon.textContent = soundEnabled ? '🔊' : '🔇';
});

/* ========================================================
   CHARACTER SELECTION INTERACTION
   ======================================================== */
selectBtn.addEventListener('click', handleSelectClick);

function handleSelectClick() {
  initAudio();
  selectClickCount++;

  if (selectClickCount === 1) {
    // FIRST CLICK: "არ აირჩიო ეს ყლე ცხვირა ინანებ"
    Sound.playBuzzer();
    biliardaCard.classList.add('shake-anim');
    setTimeout(() => biliardaCard.classList.remove('shake-anim'), 500);

    showModal({
      icon: '⚠️',
      title: 'ყურადღება! რისკი მაღალია!',
      text: 'არ აირჩიო ეს ყლე ცხვირა ინანებ',
      btnText: 'მაინც არჩევა 😈'
    });
  } else if (selectClickCount >= 2) {
    // SECOND CLICK: "ხო გთხოვე არ აირჩიო ეს ნარუტო თქო და კაი არ იშლი და ნუ იშლი"
    Sound.playAlarm();
    biliardaCard.classList.add('shake-anim');
    setTimeout(() => biliardaCard.classList.remove('shake-anim'), 500);

    showModal({
      icon: '🤦‍♂️',
      title: 'ბოლო გაფრთხილება!',
      text: 'ხო გთხოვე არ აირჩიო ეს ნარუტო თქო და კაი არ იშლი და ნუ იშლი',
      btnText: 'შესვლა თამაშში! 🚀',
      onConfirm: () => {
        enterGame();
      }
    });
  }
}

function showModal({ icon, title, text, btnText, onConfirm }) {
  modalIcon.textContent = icon;
  modalTitle.textContent = title;
  modalMessage.textContent = text;
  modalActionBtn.textContent = btnText;
  warningModal.classList.add('active');

  const handler = () => {
    warningModal.classList.remove('active');
    modalActionBtn.removeEventListener('click', handler);
    if (onConfirm) onConfirm();
  };

  modalActionBtn.addEventListener('click', handler);
}

function enterGame() {
  Sound.playWarp();
  selectScreen.classList.remove('active-screen');
  gameScreen.classList.add('active-screen');

  // Trigger Jikia scene by default
  switchRoom('jikia');
}

// Back to Character Select
backToSelectBtn.addEventListener('click', () => {
  initAudio();
  selectClickCount = 0; // Reset warning flow
  gameScreen.classList.remove('active-screen');
  selectScreen.classList.add('active-screen');
});

/* ========================================================
   ROOM SWITCHING & NAVIGATION
   ======================================================== */
roomTabs.forEach(tab => {
  tab.addEventListener('click', () => {
    initAudio();
    const targetRoom = tab.getAttribute('data-room');
    if (targetRoom !== currentRoom) {
      switchRoom(targetRoom);
    }
  });
});

function switchRoom(roomName) {
  currentRoom = roomName;

  // Update tabs
  roomTabs.forEach(t => {
    if (t.getAttribute('data-room') === roomName) {
      t.classList.add('active');
    } else {
      t.classList.remove('active');
    }
  });

  // Update scenes
  document.querySelectorAll('.room-scene').forEach(sc => {
    sc.classList.remove('active-scene');
  });

  const activeScene = document.getElementById(`scene-${roomName}`);
  if (activeScene) {
    activeScene.classList.add('active-scene');
  }

  // Hide speech bubble and clear animations
  hideSpeech();
  resetAllAnimations();

  // Run initial room action
  setTimeout(() => {
    playRoomAction(roomName);
  }, 200);
}

// Action Trigger & Replay Buttons
actionTriggerBtn.addEventListener('click', () => {
  initAudio();
  playRoomAction(currentRoom);
});

replayBtn.addEventListener('click', () => {
  initAudio();
  playRoomAction(currentRoom);
});

/* ========================================================
   SPEECH BUBBLE & FX HELPERS
   ======================================================== */
function showSpeech(text, duration = 3000) {
  if (speechTimeout) clearTimeout(speechTimeout);
  speechText.textContent = text;
  speechBubble.classList.add('active');
  speechTimeout = setTimeout(() => {
    speechBubble.classList.remove('active');
  }, duration);
}

function hideSpeech() {
  if (speechTimeout) clearTimeout(speechTimeout);
  speechBubble.classList.remove('active');
}

function spawnStars(x, y, count = 5) {
  const emojis = ['⭐', '💥', '✨', '⚡', '💫'];
  for (let i = 0; i < count; i++) {
    const star = document.createElement('div');
    star.className = 'fx-star';
    star.textContent = emojis[Math.floor(Math.random() * emojis.length)];
    star.style.left = `${x + (Math.random() * 80 - 40)}px`;
    star.style.top = `${y + (Math.random() * 80 - 40)}px`;
    fxLayer.appendChild(star);
    setTimeout(() => star.remove(), 700);
  }
}

/* ========================================================
   ROOM CHOREOGRAPHIES & ANIMATIONS
   ======================================================== */
function resetAllAnimations() {
  isAnimating = false;

  // Jikia resets
  const actorJikia = document.getElementById('actor-jikia');
  const fridge = document.getElementById('fridge');
  const fridgeDent = document.getElementById('fridgeDent');
  const jikiaNose = document.getElementById('jikiaNose');
  if (actorJikia) actorJikia.classList.remove('anim-jikia-nose-dive');
  if (fridge) fridge.classList.remove('fridge-shake');
  if (fridgeDent) fridgeDent.style.opacity = '0';
  if (jikiaNose) jikiaNose.style.opacity = '0';

  // Julaqa resets
  const actorJulaqa = document.getElementById('actor-julaqa');
  const julaqaFridge = document.getElementById('julaqaFridge');
  const julaqaFridgeDent = document.getElementById('julaqaFridgeDent');
  const diveSparks = document.getElementById('diveSparks');
  if (actorJulaqa) actorJulaqa.classList.remove('anim-julaqa-fridge-jump');
  if (julaqaFridge) julaqaFridge.classList.remove('fridge-shake');
  if (julaqaFridgeDent) julaqaFridgeDent.style.opacity = '0';
  if (diveSparks) diveSparks.style.opacity = '0';

  // Gigi resets
  const actorGigi = document.getElementById('actor-gigi');
  const paneLeft = document.getElementById('windowPaneLeft');
  const paneRight = document.getElementById('windowPaneRight');
  const heartEyes = document.getElementById('heartEyes');
  if (actorGigi) actorGigi.classList.remove('anim-gigi-window');
  if (paneLeft) paneLeft.classList.remove('open-left');
  if (paneRight) paneRight.classList.remove('open-right');
  if (heartEyes) heartEyes.style.opacity = '0';
}

function playRoomAction(room) {
  resetAllAnimations();
  isAnimating = true;

  switch (room) {
    case 'jikia':
      animateJikiaScene();
      break;
    case 'julaqa':
      animateJulaqaScene();
      break;
    case 'gigi':
      animateGigiScene();
      break;
  }
}

// 1. SCENE: JIKIA'S CRIB (მაცივარს ახტება ცხვირით)
function animateJikiaScene() {
  sceneDesc.textContent = 'ჯიქიას ბაითი: ბილიარდა ემზადება ცხვირით მაცივარზე სახტომად!';
  const actor = document.getElementById('actor-jikia');
  const fridge = document.getElementById('fridge');
  const fridgeDent = document.getElementById('fridgeDent');
  const jikiaNose = document.getElementById('jikiaNose');

  Sound.playJump();
  showSpeech('ყურადღება! ცხვირი დამიზნებულია მაცივარზე! 👃🎯', 1500);

  actor.classList.add('anim-jikia-nose-dive');

  // Launch sound and nose impact timing
  setTimeout(() => {
    Sound.playCrash();
    fridge.classList.add('fridge-shake');
    fridgeDent.style.opacity = '1';
    jikiaNose.style.opacity = '1';

    // Spawn collision star bursts
    const rect = fridge.getBoundingClientRect();
    const stageRect = document.getElementById('gameStage').getBoundingClientRect();
    spawnStars(rect.left - stageRect.left, rect.top - stageRect.top + 70, 7);

    showSpeech('აუ რამხელა ცხვირი მაქ არ შემეტია! 👃💥', 3000);
    sceneDesc.textContent = 'ჯიქიას ბაითი: "აუ რამხელა ცხვირი მაქ არ შემეტია"';
  }, 1900);

  setTimeout(() => {
    isAnimating = false;
  }, 3500);
}

// 2. SCENE: JULAQA'S CRIB (მაცივარს ახტება პირში სიგარეტით)
function animateJulaqaScene() {
  sceneDesc.textContent = 'ჯულაყას ბაითი: ბილიარდა პირში სიგარეტით მაცივარზე სახტომად ემზადება!';
  const actor = document.getElementById('actor-julaqa');
  const fridge = document.getElementById('julaqaFridge');
  const fridgeDent = document.getElementById('julaqaFridgeDent');
  const diveSparks = document.getElementById('diveSparks');

  Sound.playJump();
  showSpeech('სიგარეტი გავაბოლე... ეხლა უყურე მაცივარზე ნახტომს! 🚬🔥', 1800);

  actor.classList.add('anim-julaqa-fridge-jump');

  // Landing on top of Julaqa's fridge
  setTimeout(() => {
    Sound.playCrash();
    fridge.classList.add('fridge-shake');
    if (fridgeDent) fridgeDent.style.opacity = '1';
    if (diveSparks) diveSparks.style.opacity = '1';

    const rect = fridge.getBoundingClientRect();
    const stageRect = document.getElementById('gameStage').getBoundingClientRect();
    spawnStars(rect.left - stageRect.left + 50, rect.top - stageRect.top + 30, 8);

    showSpeech('რა ყლევარ 🤦‍♂️🚬', 3200);
    sceneDesc.textContent = 'ჯულაყას ბაითი: "რა ყლევარ" - მაცივარზე შეხტა პირში სიგარეტით!';
  }, 2100);

  setTimeout(() => {
    isAnimating = false;
  }, 3800);
}

// 3. SCENE: GIGI'S CRIB (ფანჯრიდან შემოდის და ყიყლიყო)
// "სადაც ფანჯრიდან შემოდის და ყიყლიყოებს ხედავს ანუ მარტო ფანჯარა იყოს რა და მაგიდა სადაც ყიყლიყო დევს"
function animateGigiScene() {
  sceneDesc.textContent = 'გიგის ბაითი: ბილიარდა ფანჯრიდან შემოძვრა და ყიყლიყოს შეჰყურებს!';
  const actor = document.getElementById('actor-gigi');
  const paneLeft = document.getElementById('windowPaneLeft');
  const paneRight = document.getElementById('windowPaneRight');
  const heartEyes = document.getElementById('heartEyes');

  // Open the window
  setTimeout(() => {
    Sound.playJump();
    paneLeft.classList.add('open-left');
    paneRight.classList.add('open-right');
  }, 200);

  // Character sneaks in through window
  setTimeout(() => {
    actor.classList.add('anim-gigi-window');
    showSpeech('ფანჯრიდან შემოვიპარე... აქ რაღაცის სუნია! 👀🪟', 1800);
  }, 500);

  // Sees the golden ყიყლიყო!
  setTimeout(() => {
    Sound.playHeavenly();
    heartEyes.style.opacity = '1';

    const table = document.getElementById('gigiTable');
    const stageRect = document.getElementById('gameStage').getBoundingClientRect();
    const tableRect = table.getBoundingClientRect();
    spawnStars(tableRect.left - stageRect.left + 50, tableRect.top - stageRect.top - 20, 8);

    showSpeech('ვააახ! კვერცხში ამოვლებული შემწვარი ყიყლიყოოო! ჩემი სისუსტე! 🤤🍳🍞✨', 3200);
    sceneDesc.textContent = 'გიგის ბაითი: ბილიარდა ფანჯრიდან შემოძვრა და კვერცხში ამოვლებულ შემწვარ ყიყლიყოს შეჰყურებს!';
  }, 2800);

  setTimeout(() => {
    isAnimating = false;
  }, 4700);
}
